package com.jnapanam.sportszone.identity.service;
import com.jnapanam.sportszone.common.exception.BadRequestException;import com.jnapanam.sportszone.identity.dto.*;import com.jnapanam.sportszone.identity.model.PasswordResetToken;import com.jnapanam.sportszone.identity.repository.*;import com.jnapanam.sportszone.security.TokenService;import com.jnapanam.sportszone.notification.service.NotificationService;import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.env.Environment;import org.springframework.core.env.Profiles;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PasswordRecoveryService{
 private static final String MESSAGE="If an active account exists, password reset instructions have been created.";
 private final UserRepository users;private final SmsOtpService smsOtp;private final PasswordResetTokenRepository resets;private final RefreshTokenRepository refresh;private final TokenService tokens;private final PasswordEncoder passwords;private final NotificationService notificationService;private final boolean expose;
 public PasswordRecoveryService(UserRepository users,PasswordResetTokenRepository resets,RefreshTokenRepository refresh,TokenService tokens,PasswordEncoder passwords,NotificationService notificationService,SmsOtpService smsOtp,@Value("${app.security.expose-development-reset-token:false}")boolean expose,Environment environment){this.users=users;this.smsOtp=smsOtp;this.resets=resets;this.refresh=refresh;this.tokens=tokens;this.passwords=passwords;this.notificationService=notificationService;this.expose=expose;if(expose&&(!environment.acceptsProfiles(Profiles.of("test","uat","dev","local"))||environment.acceptsProfiles(Profiles.of("prod","production"))))throw new IllegalStateException("Exposing password-reset tokens requires a non-production profile");}
 @Transactional public ForgotPasswordResponse forgot(ForgotPasswordRequest request){String raw=null;var user=users.findByEmailIgnoreCase(request.email().trim().toLowerCase(Locale.ROOT));if(user.isPresent()&&user.get().isActive()){resets.deleteByUserId(user.get().getId());raw=tokens.newRefreshToken();resets.save(new PasswordResetToken(user.get(),tokens.hash(raw),Instant.now().plusSeconds(15*60)));notificationService.notify(user.get().getId(),"SECURITY","Password reset requested","A password reset was requested for your account. The reset link/token expires in 15 minutes.");}return new ForgotPasswordResponse(MESSAGE,expose?raw:null);}
 public void requestSmsOtp(String mobile){if(users.existsByMobile(mobile.replaceAll("[ -]","")))smsOtp.passwordResetOtp(mobile);}
 @Transactional(noRollbackFor=BadRequestException.class) public void resetWithSmsOtp(SmsPasswordResetRequest request){String mobile=request.mobile().replaceAll("[ -]","");var user=users.findByMobile(mobile).orElseThrow(()->new BadRequestException("Invalid OTP or mobile"));smsOtp.verifyPasswordReset(mobile,request.otp());user.password(passwords.encode(request.newPassword()),false);refresh.findByUserIdAndRevokedAtIsNull(user.getId()).forEach(x->x.revoke());notificationService.notify(user.getId(),"SECURITY","Password changed","Your Jnapanam password was reset successfully.");}
 @Transactional public void reset(ResetPasswordRequest request){PasswordResetToken reset=resets.findByTokenHash(tokens.hash(request.token())).orElseThrow(()->new BadRequestException("Invalid or expired password reset token"));if(!reset.usable())throw new BadRequestException("Invalid or expired password reset token");reset.getUser().password(passwords.encode(request.newPassword()),false);reset.use();refresh.findByUserIdAndRevokedAtIsNull(reset.getUser().getId()).forEach(x->x.revoke());notificationService.notify(reset.getUser().getId(),"SECURITY","Password changed","Your Jnapanam password was reset successfully.");}
}
